import{_ as p,c as e,o as a,ag as _}from"./chunks/framework.BJQRJOxx.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"list/diary/爆米花.md","filePath":"list/diary/爆米花.md","lastUpdated":1763036846000}'),r={name:"list/diary/爆米花.md"};function s(o,t,i,d,n,c){return a(),e("div",null,t[0]||(t[0]=[_("<p>昨天，立冬下了一天的小雨。</p><p>今天雨停了，天空依然阴沉沉的，冷冷的风在街道上肆意扫荡，枯黄的落叶和着昨天的雨水堆积在路旁，路边卖烧饼的人哆哆嗦嗦的等待着顾客，我和几个同事裹紧了衣服走进了一家小饭馆。</p><p>简简单单吃了饭，走出饭馆，身上已经不觉得那么冷，不远处一辆三轮车上摆着几包爆米花，一个身着旧棉袄的老头在旁边收拾着炉火，看的出来他刚刚炸了一锅。</p><p>他的爆米花和电影院的不一样，电影院里卖的爆米花太甜了非常的腻，我吃过一次就不想再吃了。</p><p>我走上前去，问了问价格，5 块钱一袋，不贵，我掏出手机，扫码付款，然后随便拿了一袋，从袋口掏出来塞进嘴里，细细的咀嚼起来，热热的爆米花有着浓郁的玉米香带着丝丝甜味，真好吃。我敞开袋口分给同事，他们都摆手说“刚吃完饭，吃不下”。于是，我便不再谦让，自顾自的吃起来。</p><p>看着手里的爆米花，想起来儿时的情形。</p><p>大概是七八岁的时候，每年秋天收获了玉米，母亲都会跳出一部分又大又好的玉米专门找个袋子装起来，没到晚上或是下雨不用出去干活的时候，母亲都会带着我和妹妹开始剥玉米，把剥下来的玉米找个崭新的袋子装好，等晴天有下乡崩爆米花的人来了，把这些玉米炸成爆米花。</p><p>崩爆米花对我们这些小孩子来讲就像过年一样热闹，附近的邻居的大人们都端着玉米，小孩子就拿着大大的塑料袋，排队蹦爆米花。看着自家的玉米被塞进爆米花机，通红的炉火，热情交谈着的大人，还有我们一群小孩穿梭在其中，爆米花机在手艺人不断翻转着，开始的时候，还能听到玉米粒在机器里碰撞的声音，到后来就什么也听不到了。 不一会，只见那人抬起机器的一头，往一个黑色的套筒里一放，套筒后面有长长的袋子，我们就知道要出锅了，我们就四处逃窜，用两个食指紧紧的插进耳朵里，因为崩爆米花的声音非常响，比过年放的最响的炮还要响，所以，我们小孩一直很惧怕这种声音。</p><p>虽然堵住了耳朵还是能听到“嘭”的一声，伴随着白烟四起，我们的爆米花出锅了，我就跑过去，跟着母亲把崩好的爆米花装进塑料袋里一起回家。接下来的一段时间里，每当晚上吃完饭，我们一家人就坐在一起，吃着爆米花，看着电视……</p><p>时间一晃，已经过去好多年了，如今的我已过而立之间，小时候爆米花的味道就像一个老朋友一样一直藏在记忆深处，等你再想起时，它会微笑着跑出来和你打招呼。</p>",10)]))}const f=p(r,[["render",s]]);export{m as __pageData,f as default};
